import LocationQRview from "@/components/SettingsDialogs/LocationQRview.vue";
export default {
  components: {
    LocationQRview
  },
  props: {
    qrListLocation: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      height: 0,
      componentCheck: 0,
      fixed: true,
      tableLoading: false,
      qrLocation: false,
      qrtype: "multiple",
      rowdata: {},
      tableData: [],
      headers: [{
        title: "Location",
        value: "qr_name",
        sortable: false
      }, {
        title: "Action",
        value: "actions",
        sortable: false
      }]
    };
  },
  watch: {
    qrListLocation: {
      async handler() {
        if (this.qrListLocation == true) {
          this.tableData = [];
          this.tableData = this.rowInfo.qr_details;

          //   this.height = window.innerHeight - 100;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    qrView(item) {
      this.componentCheck = 1;
      this.rowdata = item;
      this.qrLocation = true;
    }
  }
};
